              "summary": "- 동사는 2Q26 Core 매출액 47.4억달러(+17% YoY), 영업이익 9.9억달러(+28% YoY, OPM 20.9%), EPS 0.78달러(+YoY 30%)를 기록했다. 기존 2Q 가이던스인 매출액 약 46억달러, EPS 0.73~0.77달러를 모두 상회했다.- ① AIDC향 광통신 수요 가속화: 광통신 부문 매출액은 20.7억달러(+32% YoY), 순이익은 4.4억달러(+77% YoY)를 기록했다. Enterprise Network 매출액은 12.7억달러(+32% QoQ, +65% YoY)를 기록, 이 중 AIDC 관련 매출은 전년동기 대비 약 2배 증가했다- ② Carrier Network 및 비광통신 사업은 혼조: Carrier Network 매출액은 프로젝트 인식 시점 영향으로 8.0억달러(-9% QoQ, +0.8% YoY)를 기록했다. Solar 부문 매출액은 4.4억달러(+90% YoY)로 증가했으나, 웨이퍼 공장 정비 및 설비 전환 관련 약 3,000만달러의 일회성 비용이 인식되며 순손실을 기록했다.",
