              "summary": "- 동사는 AI 인프라향 광통신 수요 확대 속 1분기 매출액 41.4억달러(+YoY 20.0%), 영업이익 6.4억달러(+YoY 43.6%, OPM 15.4%)의 호실적을 기록했다. Optical Communication(광통신) 사업부문은 1Q26 매출액 18억달러(+YoY 36%), 순이익 3.9억달러(+YoY 93%)의 가파른 성장세가 나타났다- 5월에는 엔비디아와의 장기 파트너십이 발표되었다. 동사는 엔비디아와의 협력을 통해 North Carolina와 Texas에 신규 제조 시설 3곳을 건설할 예정이다. 이를 통해 동사의 미국 내 광통신 제품 생산능력은 약 10배, 광섬유 생산능력은 50% 이상 확대될 계획이다- 동사는 ‘30년까지 매출액 연평균 성장률 19% 성장률의 장기 가이던스를 제시했다. 이에 따른 ‘28년, ‘30년 매출액은 베이스 시나리오 하 300억달러, 400억달러, 보수적 시나리오 하 270억달러, 350억달러 수준이다",
